import { ITEM_DETAIL_ENTRIES } from "../content/items";
import { ITEM_IMAGES } from "../content/itemImages";

const TIER_SUFFIX = /\|t[123]$/i;
const VARIANT_SEGMENT = /\|v:[^|]+(?=\||$)/gi;

export function normalizeItemDetailKey(value) {
  return String(value || "")
    .replace(/[\uE000-\uF8FF]/g, " ")
    .trim()
    .replace(/\s+/g, " ")
    .replace(/\s*\|\s*/g, "|")
    .toLowerCase();
}

function stripVariant(key) {
  return key
    .replace(VARIANT_SEGMENT, "")
    .replace(/\|{2,}/g, "|")
    .replace(/^\||\|$/g, "");
}

function stripTier(key) {
  return key.replace(TIER_SUFFIX, "");
}

function stripRolledRunestoneSuffixes(key) {
  return key
    .replace(/\s*\([\d.]+%\)\s*$/i, "")
    .replace(/\s+(?:\d+|i{1,3}|iv|vi{0,3}|ix)\s*$/i, "")
    .trim();
}

function makeCatalog(entries) {
  const byKey = new Map();
  const aliasToKey = new Map();

  for (const entry of entries) {
    const key = normalizeItemDetailKey(entry.key);
    byKey.set(key, entry);
    for (const alias of entry.aliases || []) {
      aliasToKey.set(normalizeItemDetailKey(alias), key);
    }
  }

  return { byKey, aliasToKey };
}

const DEFAULT_CATALOG = makeCatalog(ITEM_DETAIL_ENTRIES);

function skillCandidates(item, keyWithoutVariant) {
  const base = stripTier(keyWithoutVariant);
  const candidates = [];

  for (const modifier of item?.modifiers || []) {
    const skill = normalizeItemDetailKey(modifier);
    if (!skill) continue;
    const unbracketed = base.replace(new RegExp(`(?:\\s+|\\s*\\[)${skill}\\]?$`, "i"), "").trim();
    candidates.push(`${unbracketed} [${skill}]`);
    candidates.push(`${unbracketed} ${skill}`);
  }

  return candidates;
}

function catalogLookup(candidate, catalog) {
  const normalized = normalizeItemDetailKey(candidate);
  if (!normalized) return null;
  const direct = catalog.byKey.get(normalized);
  if (direct) return direct;
  const canonical = catalog.aliasToKey.get(normalized);
  return canonical ? catalog.byKey.get(canonical) || null : null;
}

export function resolveItemImage(imageKey, manifest = ITEM_IMAGES) {
  if (!imageKey) return null;
  const table = manifest || {};
  const normalized = normalizeItemDetailKey(imageKey);
  const noApostrophe = normalized.replace(/['"]/g, "");
  const asset =
    table[imageKey] ||
    table[normalized] ||
    (noApostrophe !== normalized ? table[noApostrophe] : null);
  if (!asset?.approved || !asset.file) return null;
  const publicBase = process.env.PUBLIC_URL || "";
  return {
    src: `${publicBase}/item-assets/${String(asset.file).replace(/^\/+/, "")}`,
    alt: asset.alt || "",
    pixelated: asset.pixelated !== false,
    animated: asset.animated === true,
    provenance: asset.provenance || "",
    rightsStatus: asset.rightsStatus || "unknown",
    renderMode: asset.renderMode || "sprite",
  };
}

function imageCandidatesFor(rawKey, item) {
  const normalized = normalizeItemDetailKey(rawKey);
  if (!normalized) return [];
  const noVariant = stripVariant(normalized);
  const base = stripTier(noVariant);
  const rolledBase = stripRolledRunestoneSuffixes(base);
  const seed = [
    normalized,
    noVariant,
    ...skillCandidates(item, noVariant),
    base,
    rolledBase,
  ];
  const out = [];
  const push = (value) => {
    const v = normalizeItemDetailKey(value);
    if (v && !out.includes(v)) out.push(v);
  };
  for (const candidate of [...new Set(seed.filter(Boolean))]) {
    push(candidate);
    // "christmas cap [farming]" -> "christmas cap farming" (legacy file stem).
    const unbracketed = candidate.replace(/\s*\[([^\]]+)\]\s*/g, " $1").replace(/\s+/g, " ").trim();
    push(unbracketed);
    // "christmas cap [farming]" / "knowledge cap [mining]" -> base cap.
    const bracketBase = candidate.replace(/\s*\[[^\]]+\]\s*/g, "").replace(/\s+/g, " ").trim();
    push(bracketBase);
    // "blessing dust (1%)" -> "blessing dust".
    const percentBase = candidate.replace(/\s*\([\d.]+%\)\s*$/i, "").trim();
    push(percentBase);
    // "ruby's fire" -> "rubys fire", "bottle o' enchanting" -> "bottle o enchanting".
    push(candidate.replace(/['"]/g, ""));
    push(unbracketed.replace(/['"]/g, ""));
    push(bracketBase.replace(/['"]/g, ""));
    push(percentBase.replace(/['"]/g, ""));
  }
  return out;
}

export function resolveItemImageForItem(item, manifest = ITEM_IMAGES) {
  if (!item) return null;
  const raw = normalizeItemDetailKey(item.key || item.rawName || item.rawKey || item.name);
  if (!raw) return null;
  const table = manifest || {};
  for (const candidate of imageCandidatesFor(raw, item)) {
    const asset = table[candidate] || table[candidate.replace(/['"]/g, "")];
    if (asset?.approved && asset.file) return resolveItemImage(candidate, table);
  }
  return null;
}

export function getItemPresentation(item, options = {}) {
  if (!item) return null;
  const catalog = options.entries ? makeCatalog(options.entries) : DEFAULT_CATALOG;
  const manifest = options.imageManifest || ITEM_IMAGES;
  const raw = normalizeItemDetailKey(item.key || item.rawName || item.rawKey || item.name);
  if (!raw) return null;

  const noVariant = stripVariant(raw);
  const candidates = [raw, noVariant, ...skillCandidates(item, noVariant)];
  const base = stripTier(noVariant);
  if (base !== noVariant) candidates.push(base);
  const rolledBase = stripRolledRunestoneSuffixes(base);
  if (rolledBase !== base) candidates.push(rolledBase);

  let entry = null;
  for (const candidate of [...new Set(candidates)]) {
    entry = catalogLookup(candidate, catalog);
    if (entry) break;
  }

  // Image coverage is independent of curated descriptions so ordinary
  // market items (vanilla, fish, books, discs, eggs, spawners) still get
  // artwork without requiring a hand-authored reference entry first.
  let image = null;
  if (entry) {
    image =
      resolveItemImage(entry.imageKey, manifest) ||
      resolveItemImage(entry.key, manifest) ||
      resolveItemImageForItem({ ...item, key: entry.key }, manifest) ||
      resolveItemImageForItem(item, manifest);
  } else {
    image = resolveItemImageForItem(item, manifest);
  }
  if (!entry && !image) return null;
  if (!entry) {
    return {
      key: raw,
      enchantments: [],
      details: [],
      image,
    };
  }

  return {
    key: entry.key,
    enchantments: entry.enchantments || [],
    details: entry.details || [],
    image,
  };
}

export function validateItemDetailsCatalog(entries = ITEM_DETAIL_ENTRIES) {
  const errors = [];
  const identities = new Map();

  for (const [index, entry] of entries.entries()) {
    const label = entry?.key || `entry ${index}`;
    const key = normalizeItemDetailKey(entry?.key);
    if (!key) errors.push(`${label}: missing key`);
    if (key === "placeholder") errors.push(`${label}: placeholder record is not allowed`);
    if (!entry?.enchantments?.length && !entry?.details?.length) {
      errors.push(`${label}: no item details`);
    }

    for (const identity of [entry?.key, ...(entry?.aliases || [])]) {
      const normalized = normalizeItemDetailKey(identity);
      if (!normalized) continue;
      const owner = identities.get(normalized);
      if (owner && owner !== key) errors.push(`${label}: duplicate identity ${normalized}`);
      identities.set(normalized, key);
    }

    for (const enchantment of entry?.enchantments || []) {
      if (!String(enchantment?.name || "").trim()) errors.push(`${label}: unnamed enchantment`);
      if (enchantment?.level != null && (!Number.isInteger(enchantment.level) || enchantment.level <= 0)) {
        errors.push(`${label}: invalid enchantment level`);
      }
    }
    for (const detail of entry?.details || []) {
      if (!String(detail || "").trim()) errors.push(`${label}: empty detail`);
    }
  }

  return errors;
}

export { ITEM_DETAIL_ENTRIES };
