import enchantedBookImages from "./item-images/enchanted-book.json";
import fishImages from "./item-images/fish.json";
import musicDiscImages from "./item-images/music-disc.json";
import runestoneImages from "./item-images/runestone.json";
import resourceImages from "./item-images/resource.json";
import setGearImages from "./item-images/set-gear.json";
import spawnEggImages from "./item-images/spawn-egg.json";
import spawnerImages from "./item-images/spawner.json";
import uniqueRelicImages from "./item-images/unique-relic.json";
import utilityImages from "./item-images/utility.json";
import vanillaImages from "./item-images/vanilla.json";

// Deliberately explicit and assembled at build time: the browser never probes
// guessed asset URLs, while source and rights metadata stay attached.
export const ITEM_IMAGE_ENTRIES = Object.freeze([
  ...vanillaImages,
  ...enchantedBookImages,
  ...musicDiscImages,
  ...fishImages,
  ...spawnEggImages,
  ...spawnerImages,
  ...runestoneImages,
  ...resourceImages,
  ...setGearImages,
  ...uniqueRelicImages,
  ...utilityImages,
]);

export const ITEM_IMAGES = Object.freeze(
  Object.fromEntries(
    ITEM_IMAGE_ENTRIES.flatMap((entry) => [entry.key, ...(entry.aliases || [])]
      .map((identity) => [identity, Object.freeze(entry)])),
  ),
);

export default ITEM_IMAGES;
